function def(ing) {
  const aliases = ing.aliases || [];
  return {
    ...ing,
    name: bi(ing.nameEn, ing.nameKu),
    description: bi(ing.descriptionEn, ing.descriptionKu),
    whoShouldUse: bi(ing.whoShouldUseEn, ing.whoShouldUseKu),
    whoShouldAvoid: bi(ing.whoShouldAvoidEn, ing.whoShouldAvoidKu),
    bestSkinTypes: bi(ing.bestSkinTypesEn, ing.bestSkinTypesKu),
    benefits: bi(ing.benefitsEn, ing.benefitsKu),
    sideEffects: bi(ing.sideEffectsEn, ing.sideEffectsKu),
    pregnancySafety: bi(ing.pregnancySafetyEn, ing.pregnancySafetyKu),
    timing: bi(ing.timingEn, ing.timingKu),
    frequency: bi(ing.frequencyEn, ing.frequencyKu),
    mixesWith: bi(ing.mixesWithEn, ing.mixesWithKu),
    avoidWith: bi(ing.avoidWithEn, ing.avoidWithKu),
    percentageRange: bi(ing.percentageRangeEn, ing.percentageRangeKu),
    famousProducts: bi(ing.famousProductsEn, ing.famousProductsKu),
    evidenceLevel: bi(ing.evidenceLevelEn, ing.evidenceLevelKu),
    mythVsFact: bi(ing.mythVsFactEn, ing.mythVsFactKu),
    texture: bi(ing.textureEn, ing.textureKu),
    ph: bi(ing.phEn || "Not typically listed", ing.phKu || "زۆرجار تۆمار ناکرێت"),
    beginnerTip: bi(ing.beginnerTipEn, ing.beginnerTipKu),
    dermNote: bi(ing.dermNoteEn, ing.dermNoteKu),
    educationalNote: bi(ing.educationalNoteEn, ing.educationalNoteKu),
    faqs: (ing.faqs || []).map((f) => ({
      q: bi(f.qEn, f.qKu),
      a: bi(f.aEn, f.aKu),
    })),
    aliases,
    matchNames: [ing.nameEn, ...(aliases)].map((s) => String(s).toLowerCase()),
    searchText: [
      ing.nameEn, ing.nameKu, ...(aliases),
      ing.descriptionEn, ing.descriptionKu,
      ing.benefitsEn, ing.benefitsKu,
      ing.whoShouldUseEn, ing.category,
      ...(ing.filters || []),
      ...(ing.famousProductsEn || "").split(/[,·]/),
    ].filter(Boolean).join(" ").toLowerCase(),
  };
}

