export const BEAUTY_INGREDIENTS = RAW_INGREDIENTS.map(def);

export function getIngredientById(id) {
  return BEAUTY_INGREDIENTS.find((i) => i.id === id) || null;
}

export function localizeIngredient(ing, lang = "en") {
  if (!ing) return null;
  return {
    ...ing,
    name: L(ing.name, lang),
    description: L(ing.description, lang),
    whoShouldUse: L(ing.whoShouldUse, lang),
    whoShouldAvoid: L(ing.whoShouldAvoid, lang),
    bestSkinTypes: L(ing.bestSkinTypes, lang),
    benefits: L(ing.benefits, lang),
    sideEffects: L(ing.sideEffects, lang),
    pregnancySafety: L(ing.pregnancySafety, lang),
    timing: L(ing.timing, lang),
    frequency: L(ing.frequency, lang),
    mixesWith: L(ing.mixesWith, lang),
    avoidWith: L(ing.avoidWith, lang),
    percentageRange: L(ing.percentageRange, lang),
    famousProducts: L(ing.famousProducts, lang),
    evidenceLevel: L(ing.evidenceLevel, lang),
    mythVsFact: L(ing.mythVsFact, lang),
    texture: L(ing.texture, lang),
    ph: L(ing.ph, lang),
    beginnerTip: L(ing.beginnerTip, lang),
    dermNote: L(ing.dermNote, lang),
    educationalNote: L(ing.educationalNote, lang),
    faqs: (ing.faqs || []).map((f) => ({ q: L(f.q, lang), a: L(f.a, lang) })),
    sectionLabel: L(INGREDIENT_SECTIONS.find((s) => s.id === ing.category)?.label || "", lang),
  };
}

export function getLocalizedIngredients(lang = "en") {
  return BEAUTY_INGREDIENTS.map((i) => localizeIngredient(i, lang));
}

export function matchProductsForIngredient(ingredient, products = []) {
  const needles = ingredient.matchNames || [ingredient.nameEn?.toLowerCase()];
  return products.filter((p) =>
    (p.ingredients || []).some((raw) => {
      const low = String(raw).toLowerCase();
      return needles.some((n) => low.includes(n) || n.includes(low));
    })
  );
}
